package com.termux.app.workspace;
import android.app.*;import android.view.*;import android.widget.*;import com.termux.R;import com.termux.app.TermuxActivity;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class WorkspaceChatFileChoicesTest {
 WorkspaceFileBrowser browser;TermuxActivity activity;LinearLayout rows;AtomicReference<List<ProjectFiles.Entry>> selected=new AtomicReference<>();
 void set(String name,Object value)throws Exception{Field f=WorkspaceFileBrowser.class.getDeclaredField(name);f.setAccessible(true);f.set(browser,value);}Object get(String name)throws Exception{Field f=WorkspaceFileBrowser.class.getDeclaredField(name);f.setAccessible(true);return f.get(browser);}
 void setupBrowser(int limit)throws Exception{activity=Robolectric.buildActivity(TermuxActivity.class).get();activity.setTheme(R.style.Theme_Termux_Black);FileSort.save(activity,FileSort.Order.NAME_ASC);WorkspaceStore.Session p=new WorkspaceStore.Session();p.environment="ubuntu";browser=new WorkspaceFileBrowser(activity,p,"/source",null);browser.setChatFileChoices((source,files)->selected.set(files),limit);set("busy",true);browser.show();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();set("busy",false);ProjectFiles.Listing listing=new ProjectFiles.Listing();listing.path="/source";listing.entries.add(new ProjectFiles.Entry("/source","one.zip",false,10));listing.entries.add(new ProjectFiles.Entry("/source","two.stl",false,20));set("listing",listing);Method render=WorkspaceFileBrowser.class.getDeclaredMethod("render");render.setAccessible(true);render.invoke(browser);rows=(LinearLayout)get("rows");}
 @After public void close(){if(browser!=null)browser.close();}
 @Test public void ordinaryTapKeepsSingleFileDraftSelection()throws Exception{setupBrowser(4);AlertDialog dialog=(AlertDialog)get("dialog");assertEquals(View.GONE,dialog.getButton(-1).getVisibility());rows.getChildAt(0).performClick();assertEquals(1,selected.get().size());assertEquals("one.zip",selected.get().get(0).name);assertFalse(dialog.isShowing());}
 @Test public void longPressShowsCheckboxesAndWaitsForExplicitConfirmation()throws Exception{setupBrowser(4);AlertDialog dialog=(AlertDialog)get("dialog");assertTrue(rows.getChildAt(0).performLongClick());assertNull(selected.get());assertEquals(View.VISIBLE,dialog.getButton(-1).getVisibility());ViewGroup first=(ViewGroup)rows.getChildAt(0);assertTrue(first.getChildAt(0) instanceof CheckBox);assertTrue(((CheckBox)first.getChildAt(0)).isChecked());rows.getChildAt(1).performClick();assertNull(selected.get());assertTrue(dialog.getButton(-1).getText().toString().contains("2"));dialog.getButton(-1).performClick();assertEquals(2,selected.get().size());assertEquals("one.zip",selected.get().get(0).name);assertEquals("two.stl",selected.get().get(1).name);}
 @Test public void availableDraftSlotsBoundSelectionAndCancelledPickerDoesNotSend()throws Exception{setupBrowser(1);rows.getChildAt(0).performLongClick();rows.getChildAt(1).performClick();assertEquals(1,((Map<?,?>)get("selectedFiles")).size());assertNull(selected.get());((AlertDialog)get("dialog")).getButton(-2).performClick();assertNull(selected.get());}
}
